import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
import {resolve} from 'node:path';
const load = name => import(pathToFileURL(resolve(name)).href);
const m=await load('src/checkout.ts'); for(const [p,q,t,d] of [[10,2,.2,.1],[0,8,.2,.1],[2.5,3,0,.25]]) { const s=p*q; assert.equal(m.subtotal(p,q),s); assert.equal(m.taxAmount(s,t),s*t); assert.equal(m.discountAmount(s,d),s*d); assert.ok(Math.abs(m.calculateTotal(p,q,t,d)-(s+s*t-s*d))<1e-9); }

