import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
import {resolve} from 'node:path';
const load = name => import(pathToFileURL(resolve(name)).href);
const m=await load('src/validators.js'); for(const v of [null,undefined,'',' \t','Ada',' X ']) { const empty=v==null || !v.trim(); assert.equal(m.isEmpty(v),empty); for(const f of ['validateName','validateEmail','validateCity']) assert.equal(m[f](v),!empty); }
import {readFileSync} from 'node:fs'; assert.ok((readFileSync('src/validators.js','utf8').match(/isEmpty\s*\(/g)||[]).length>=4,'validators must share isEmpty');
